#!/usr/bin/env sage
"""reduce26_crosscheck_v1.sage -- verify the convolution identity (#26) holds AND cross-check the
P^1 character-sum reduction. The A1 self-test already certified f[d]=h2[d]-(h1*h1)[d]=0 for d!=0.
This script: (1) re-verifies the convolution identity at p=43, (2) computes the rational/conjugate
pair sums for several R, (3) computes sum_t chi_2(gF) independently, and reconciles the three.
If sum_t chi_2(gF) != 0 but the convolution identity holds, the reduction's claimed EQUIVALENCE has
a gap (not #26)."""


# This file was *autogenerated* from the file reduce26_crosscheck_v1.sage
from sage.all_cmdline import *   # import sage library

_sage_const_0 = Integer(0); _sage_const_1 = Integer(1); _sage_const_2 = Integer(2); _sage_const_43 = Integer(43); _sage_const_7 = Integer(7); _sage_const_3 = Integer(3); _sage_const_5 = Integer(5)
from sage.all import GF, EllipticCurve, ZZ
import audit_n1_vsign_v2_core as core


def chi2(a, p):
    a = int(a) % p
    if a == _sage_const_0 : return _sage_const_0 
    return _sage_const_1  if pow(a, (p-_sage_const_1 )//_sage_const_2 , p) == _sage_const_1  else -_sage_const_1 


if __name__ == "__main__":
    p, A, B = _sage_const_43 , _sage_const_0 , _sage_const_7 
    Fp = GF(p); Fp2 = GF(p**_sage_const_2 , 'a')
    E = EllipticCurve(Fp, [A, B]); n = E.order()
    G = next(P for P in E if P.order() == n)
    print("p=%d n=%d  E:y^2=x^3+%d" % (p, n, B))

    # (1) convolution identity (#26) via the V2-V1^2 form (A1 route)
    dl = core.dlog_table(p, n); h1 = core.hist_k1(p, n, dl); h2 = core.hist_k2(p, n, dl)
    conv = core.polymul_mod_cyc(h1, h1, n)
    fZ = [h2[d] - conv[d] for d in range(n)]
    off0 = fZ[_sage_const_1 :]
    const_ok = len(set(off0)) == _sage_const_1 
    c = off0[_sage_const_0 ] if off0 else _sage_const_0 
    eps = core.legendre(-_sage_const_1 , p)
    measured = fZ[_sage_const_0 ] - c
    print("(1) convolution identity: const_off_zero=%s c=%d  V2-V1^2=%d target=%d  HOLDS=%s"
          % (const_ok, c, measured, -_sage_const_2 *eps*p, const_ok and measured == -_sage_const_2 *eps*p))

    # (2) for several R: rational-sum and conjugate-sum of chi_2(y1 y2)
    print("\n(2) pair sums by R, and (3) sum_t chi_2(gF):")
    for e in (_sage_const_1 , _sage_const_2 , _sage_const_3 , _sage_const_5 , _sage_const_7 ):
        R = e*G
        if R.is_zero(): continue
        E2 = E.change_ring(Fp2); R2 = E2(R[_sage_const_0 ], R[_sage_const_1 ])
        seen = set(); sr = sc = _sage_const_0 ; nr = nc = _sage_const_0 
        # also collect the t->cgF table for sum_t chi_2(gF)
        ttable = {}   # t (as F_p int) -> cgF  (but careful: which t coordinate?)
        xR, yR = ZZ(R[_sage_const_0 ]), ZZ(R[_sage_const_1 ])
        for x1 in Fp2:
            rhs = x1**_sage_const_3  + A*x1 + B
            if not rhs.is_square(): continue
            y1 = rhs.sqrt()
            for sg in (_sage_const_1 , -_sage_const_1 ):
                P1 = E2(x1, sg*y1); P2 = R2 - P1
                if P1.is_zero() or P2.is_zero(): continue
                inFp = (P1[_sage_const_0 ] in Fp) and (P1[_sage_const_1 ] in Fp)
                Pf = E2(P1[_sage_const_0 ]**p, P1[_sage_const_1 ]**p)
                is_conj = (Pf == P2) and not inFp
                is_rat = inFp and ((R2 - P1)[_sage_const_0 ] in Fp)
                if not (is_conj or is_rat): continue
                key = frozenset((tuple(P1), tuple(P2)))
                if key in seen: continue
                seen.add(key)
                py = P1[_sage_const_1 ]*P2[_sage_const_1 ]
                if py != py**p: continue
                cF = chi2(py, p)
                cg = _sage_const_1  if is_rat else -_sage_const_1 
                if is_rat: sr += cF; nr += _sage_const_1 
                else: sc += cF; nc += _sage_const_1 
                # the t-coordinate x1 + x(R-P1):
                if x1 == xR: continue
                xRmP = ((yR + P1[_sage_const_1 ])/(xR - P1[_sage_const_0 ]))**_sage_const_2  - P1[_sage_const_0 ] - xR   # x(R-P1)
                t = P1[_sage_const_0 ] + xRmP
                if t in Fp:
                    ttable[int(t)] = (cg, cF)
        sum_gF = sum(cg*cF for (cg,cF) in ttable.values())
        print("  R=[%d]G: rat(%d,sum=%d) conj(%d,sum=%d) diff=%d  | sum_t chi_2(gF) over %d t-values = %d"
              % (e, nr, sr, nc, sc, sr-sc, len(ttable), sum_gF))

